            && !digits.starts_with('0')
            && digits.bytes().all(|b| b.is_ascii_digit());
        if !canonical {
            return Err(NotAHandle);
        }
        // Too many digits to fit: no such handle can have been issued.
        digits.parse().map(ReceiptHandle).map_err(|_| NotAHandle)
    }
}

/// Hands out 1, 2, 3, ... for message ids and receipt handles.
#[derive(Debug, Default)]
pub struct Counter {
    last: u64,
}

impl Counter {
    pub fn next_message_id(&mut self) -> MessageId {
        self.last += 1;
        MessageId(self.last)
    }

    pub fn next_receipt_handle(&mut self) -> ReceiptHandle {
        self.last += 1;
        ReceiptHandle(self.last)
    }

    /// Whether this counter has already handed out `handle`.
    pub fn has_issued(&self, handle: ReceiptHandle) -> bool {
        handle.0 <= self.last
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn queue_name_rules() {
        let long_base = "a".repeat(75);
        let cases = [
            ("jobs", true),
            ("A-z_09", true),
            ("jobs.fifo", true),
            ("", false),
            (".fifo", false),
            ("a.fifo.fifo", false),
            ("jobs.txt", false),
            ("jo bs", false),
            ("j\u{e9}", false),
            (&*"a".repeat(80), true),
            (&*"a".repeat(81), false),
            (&*format!("{long_base}.fifo"), true),
            (&*format!("{long_base}a.fifo"), false),
        ];
        for (name, valid) in cases {
            assert_eq!(QueueName::parse(name).is_some(), valid, "name {name:?}");
        }
    }

    #[test]
    fn tag_rules() {
        let cases = [
            ("g1", true),
            ("A-_z", true),
            ("", false),
            ("a.b", false),
            (&*"x".repeat(128), true),
            (&*"x".repeat(129), false),
        ];
        for (text, valid) in cases {
            assert_eq!(Tag::parse(text).is_some(), valid, "tag {text:?}");
        }
    }

    #[test]
    fn receipt_handle_accepts_only_canonical_text() {
        assert_eq!("r-1".parse(), Ok(ReceiptHandle(1)));
        assert_eq!("r-907".parse(), Ok(ReceiptHandle(907)));
        for text in [
            "r-0", "r-01", "R-1", "r-1 ", " r-1", "r-", "r-+1", "r--1", "m-1", "r-1.0",
            "r-99999999999999999999999",
        ] {
            assert_eq!(text.parse::<ReceiptHandle>(), Err(NotAHandle), "text {text:?}");
        }
    }

    #[test]
    fn counter_issues_from_one() {
        let mut counter = Counter::default();
        assert!(!counter.has_issued(ReceiptHandle(1)));
        assert_eq!(counter.next_receipt_handle().to_string(), "r-1");
        assert_eq!(counter.next_receipt_handle().to_string(), "r-2");
        assert!(counter.has_issued(ReceiptHandle(2)));
        assert!(!counter.has_issued(ReceiptHandle(3)));
    }
}

