            panic!("expected CreateQueue");
        };
        assert_eq!(attributes, want);
    }

    #[test]
    fn rejects_bad_attribute_values() {
        let cases = [
            r#""x""#,
            r#"{"VisibilityTimeout": 43201}"#,
            r#"{"DelaySeconds": 901}"#,
            r#"{"RetentionSeconds": 59}"#,
            r#"{"Fifo": "true"}"#,
            r#"{"ContentBasedDeduplication": 1}"#,
            r#"{"DeadLetterQueue": 1}"#,
            r#"{"MaxReceiveCount": 0}"#,
            r#"{"Unknown": 1}"#,
