            "not json",
            "[1]",
            "\"CreateQueue\"",
            "{}",
            r#"{"Command": 5}"#,
            r#"{"Command": null}"#,
            r#"{"Command": "createQueue"}"#,
            r#"{"Command": "Tick", "Seconds": 1} {}"#,
