#[test]
fn send_message_rule_order() {
    let mut client = Client::default();
    client.create("std", json!({}));
    client.create("f.fifo", json!({"Fifo": true}));
    let cases = [
        (json!({"QueueName": "std", "Body": "b", "DeduplicationId": "d"}), "UnsupportedOperation"),
        (json!({"QueueName": "f.fifo", "Body": "b", "DelaySeconds": 0}), "UnsupportedOperation"),
        (json!({"QueueName": "f.fifo", "Body": "b"}), "MissingParameter"),
        (json!({"QueueName": "f.fifo", "Body": "b", "GroupId": "g"}), "MissingParameter"),
        (json!({"QueueName": "nope", "Body": ""}), "InvalidParameterValue"),
        (json!({"QueueName": "nope", "Body": "b"}), "QueueDoesNotExist"),
        (json!({"QueueName": "std"}), "MissingParameter"),
    ];
    for (mut request, want) in cases {
