#[test]
fn fifo_deduplication_window_is_300_seconds_from_acceptance() {
    let mut client = Client::default();
    client.create("q.fifo", json!({"Fifo": true}));
    let send = |group: &str| {
        json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": "x", "GroupId": group, "DeduplicationId": "d"})
    };
    assert_eq!(client.call(send("g")), json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    client.tick(299);
    // Duplicates ignore the group and do not extend the window.
    assert_eq!(client.call(send("h")), json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    client.receive("q.fifo", 1);
    client.call(json!({"Command": "DeleteMessage", "QueueName": "q.fifo", "ReceiptHandle": "r-1"}));
    assert_eq!(client.call(send("g")), json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    client.tick(1);
    assert_eq!(client.call(send("g")), json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
    assert_eq!(client.counts("q.fifo"), [1, 0, 0]);
}

#[test]
fn content_based_deduplication_uses_the_body() {
    let mut client = Client::default();
    client.create("q.fifo", json!({"Fifo": true, "ContentBasedDeduplication": true}));
    let send = |body: &str| json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": body, "GroupId": "g"});
    assert_eq!(client.call(send("same")), json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(client.call(send("same")), json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(client.call(send("other")), json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
    // A DeduplicationId equal to an earlier body is the same id.
    let response = client.call(json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": "z", "GroupId": "g", "DeduplicationId": "other"}));
    assert_eq!(response, json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
}

#[test]
fn deduplication_is_per_queue() {
    let mut client = Client::default();
